package com.chahinaz.pos.operations;
import com.chahinaz.pos.audit.AuditService;import com.chahinaz.pos.catalogue.*;import com.chahinaz.pos.employee.*;import com.chahinaz.pos.sales.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class ReturnService {private final SaleRepository sales;private final SaleReturnRepository returns;private final SaleReturnItemRepository returnItems;private final ProductRepository products;private final InventoryMovementRepository movements;private final EmployeeRepository employees;private final RegisterService registers;private final AuditService audit;public ReturnService(SaleRepository s,SaleReturnRepository r,SaleReturnItemRepository ri,ProductRepository p,InventoryMovementRepository m,EmployeeRepository e,RegisterService rs,AuditService a){sales=s;returns=r;returnItems=ri;products=p;movements=m;employees=e;registers=rs;audit=a;}
 public record ItemInput(@NotNull UUID saleItemId,@Min(1) int quantity,boolean restockable){} public record Input(@NotEmpty List<@Valid ItemInput> items,@NotNull PaymentType refundMethod,Boolean whishManuallyRecorded,@NotBlank @Size(min=3,max=500) String reason){} public record View(UUID id,UUID saleId,BigDecimal refundUsd,BigDecimal refundLbp,PaymentType method,String reason){}
 @Transactional public View create(UUID saleId,Input in,Authentication auth){Employee e=employees.findByUsernameIgnoreCase(auth.getName()).orElseThrow();Sale sale=sales.findLocked(saleId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Sale not found"));if(sale.status!=SaleStatus.COMPLETED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only completed sales can be returned");if(in.reason()==null||in.reason().trim().length()<3||in.items()==null||in.items().isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Return items and reason are required");if(in.refundMethod()==PaymentType.WHISH_MANUAL&&!Boolean.TRUE.equals(in.whishManuallyRecorded()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Whish refund must be manually recorded");SaleReturn r=new SaleReturn(sale,e,in.refundMethod(),in.reason().trim());r.whishManuallyRecorded=Boolean.TRUE.equals(in.whishManuallyRecorded());if(in.refundMethod()!=PaymentType.WHISH_MANUAL)r.registerSessionId=registers.requireOpen(e).id;returns.saveAndFlush(r);BigDecimal total=BigDecimal.ZERO;
  for(ItemInput request:in.items()){if(request.quantity()<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Return quantity must be positive");SaleItem item=sale.items.stream().filter(x->x.id.equals(request.saleItemId())).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Sale item not found"));long remaining=item.quantity-returnItems.returnedQuantity(item.id);if(request.quantity()>remaining)throw new ResponseStatusException(HttpStatus.CONFLICT,"Return quantity exceeds remaining sold quantity");BigDecimal amount=item.lineTotalUsd.multiply(BigDecimal.valueOf(request.quantity())).divide(BigDecimal.valueOf(item.quantity),2,RoundingMode.HALF_UP);SaleReturnItem ri=new SaleReturnItem(r,item,request.quantity(),amount,request.restockable());r.items.add(ri);total=total.add(amount);if(request.restockable()){Product p=products.findLockedById(item.getProduct().getId()).orElseThrow();p.restoreStock(request.quantity());products.save(p);movements.save(new InventoryMovement(p,MovementType.RETURN,request.quantity(),p.getStockQuantity(),"Return for "+sale.saleNumber,e.getId(),sale.getId()).forReturn(r.id));}}
  if(in.refundMethod()==PaymentType.LBP_CASH){r.refundLbp=total.multiply(sale.exchangeRate).setScale(0,RoundingMode.HALF_UP);}else r.refundUsd=total.setScale(2);returns.saveAndFlush(r);audit.record(e.getId(),"SALE_RETURN","sale_return",r.id.toString(),null,"sale="+sale.saleNumber+"; USD="+total);return new View(r.id,sale.getId(),r.refundUsd,r.refundLbp,r.refundMethod,r.reason);}
}
